// lib/store.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface User {
  user_id: number;
  email: string;
  name: string; 
}



export type PrimaryTab = "iris" | "screener" | "profile";

interface AppState {
  // Existing State
  user: User | null;
  threadId: string | null;

  // New UI State
  activePrimaryTab: PrimaryTab;
  isSecondarySidebarOpen: boolean;

  // Existing Actions
  setUser: (user: User | null) => void;
  setThreadId: (threadId: string | null) => void;
  
  // New Actions
  setActivePrimaryTab: (tab: PrimaryTab) => void;
  toggleSecondarySidebar: () => void;
}

export const useAppStore = create<AppState>()(
  // Use the 'persist' middleware to save state to localStorage
  persist(
    (set) => ({
      // --- Initial State Values ---
      user: null,
      threadId: null,
      activePrimaryTab: "iris", // Default to the 'iris' chat view
      isSecondarySidebarOpen: true, // Default to open as in the screenshot

      // --- Actions ---
      setUser: (user) => set({ user }),
      setThreadId: (threadId) => set({ threadId }),
      
      setActivePrimaryTab: (tab) => set({ activePrimaryTab: tab }),
      toggleSecondarySidebar: () =>
        set((state) => ({ isSecondarySidebarOpen: !state.isSecondarySidebarOpen })),
    }),
    {
      // Configuration for the persist middleware
      name: "iris-app-storage", // Name of the item in localStorage
      // We only want to persist the user session and threadId, not the UI state
      partialize: (state) => ({ user: state.user, threadId: state.threadId }),
    }
  )
);
